+    __ add(dst, dst, tmp);
+
+    // Small backward copies benefit from m1 for the same reason as small
+    // forward copies. The end pointers above are also used by the tail loop.
+    if (max_elems_small > 0) {
+      __ li(tmp, max_elems_small);
+      __ bleu(cnt, tmp, tail);
